ge_reference":"player-asset:pwhl-taylor-house/starter/pwhl-taylor-house-starter","visual_metadata":{"treatment":"neutral-placeholder","accent":"#7f8c8d","frame":"starter"}},{"card_id":"pwhl-taylor-otremba-base","image_reference":"player-asset:pwhl-taylor-otremba/base/pwhl-taylor-otremba-base","visual_metadata":{"treatment":"neutral-placeholder","accent":"#5e7180","frame":"standard"}},{"card_id":"pwhl-taylor-otremba-starter","image_reference":"player-asset:pwhl-taylor-otremba/starter/pwhl-taylor-otremba-starter","visual_metadata":{"treatment":"neutral-placeholder","accent":"#7f8c8d","frame":"starter"}},{"card_id":"pwhl-tereza-vanisova-base","image_reference":"player-asset:pwhl-tereza-vanisova/base/pwhl-tereza-vanisova-base","visual_metadata":{"treatment":"neutral-placeholder","accent":"#5e7180","frame":"standard"}},{"card_id":"pwhl-theresa-schafzahl-base","image_reference":"player-asset:pwhl-theresa-schafzahl/base/pwhl-theresa-schafzahl-base","visual_metadata":{"treatment":"neutral-placeholder","accent":"#5e7180","frame":"standard"}},{"card_id":"pwhl-tia-chan-base","image_reference":"player-asset:pwhl-tia-chan/base/pwhl-tia-chan-base","visual_metadata":{"treatment":"neutral-placeholder","accent":"#5e7180","frame":"standard"}},{"card_id":"pwhl-tova-henderson-base","image_reference":"player-asset:pwhl-tova-henderson/base/pwhl-tova-henderson-base","visual_metadata":{"treatment":"neutral-placeholder","accent":"#5e7180","frame":"standard"}},{"card_id":"pwhl-tova-henderson-starter","image_reference":"player-asset:pwhl-tova-henderson/starter/pwhl-tova-henderson-starter","visual_metadata":{"treatment":"neutral-placeholder","accent":"#7f8c8d","frame":"starter"}},{"card_id":"pwhl-vita-poniatovskaia-base","image_reference":"player-asset:pwhl-vita-poniatovskaia/base/pwhl-vita-poniatovskaia-base","visual_metadata":{"treatment":"neutral-placeholder","accent":"#5e7180","frame":"standard"}},{"card_id":"pwhl-vita-poniatovskaia-starter","image_reference":"player-asset:pwhl-vita-poniatovskaia/starter/pwhl-vita-poniatovskaia-starter","visual_metadata":{"treatment":"neutral-placeholder","accent":"#7f8c8d","frame":"starter"}},{"card_id":"pwhl-zoe-boyd-base","image_reference":"player-asset:pwhl-zoe-boyd/base/pwhl-zoe-boyd-base","visual_metadata":{"treatment":"neutral-placeholder","accent":"#5e7180","frame":"standard"}}]$card_asset_catalog$::jsonb;
  expected_count bigint;
  distinct_count bigint;
  catalog_count bigint;
  matched_count bigint;
  updated_count bigint;
begin
  expected_count := jsonb_array_length(asset_rows);

  select count(distinct seeded.card_id)
  into distinct_count
  from jsonb_to_recordset(asset_rows) as seeded(
    card_id text,
    image_reference text,
    visual_metadata jsonb
  );

  if distinct_count <> expected_count then
    raise exception 'Card asset projection contains duplicate card IDs (% distinct / % rows).', distinct_count, expected_count;
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(asset_rows) as seeded(
      card_id text,
      image_reference text,
      visual_metadata jsonb
    )
    where seeded.image_reference is null or seeded.image_reference = ''
      or jsonb_typeof(seeded.visual_metadata) <> 'object'
  ) then
    raise exception 'Card asset projection contains an empty reference or invalid visual metadata.';
  end if;

  select count(*)
  into catalog_count
  from public.card_catalog;

  if catalog_count <> expected_count then
    raise exception 'Card asset projection expects % cards, but public.card_catalog contains %.', expected_count, catalog_count;
  end if;

  select count(*)
  into matched_count
  from public.card_catalog as catalog
  inner join jsonb_to_recordset(asset_rows) as seeded(
    card_id text,
    image_reference text,
    visual_metadata jsonb
  ) on seeded.card_id = catalog.card_id;

  if matched_count <> expected_count then
    raise exception 'Card asset projection matched % of % cards.', matched_count, expected_count;
  end if;

  update public.card_catalog as catalog
  set
    image_reference = seeded.image_reference,
    visual_metadata = seeded.visual_metadata
  from jsonb_to_recordset(asset_rows) as seeded(
    card_id text,
    image_reference text,
    visual_metadata jsonb
  )
  where catalog.card_id = seeded.card_id;

  get diagnostics updated_count = row_count;
  if updated_count <> expected_count then
    raise exception 'Card asset projection updated % of % cards.', updated_count, expected_count;
  end if;
end
$card_asset_projection$;
-- END GENERATED CARD ASSET REFERENCES
